const decoded = new Map<OgFontKey, ArrayBuffer>();

/** Decode once per process; returns the WOFF bytes for Satori. */
export function ogFontData(key: OgFontKey): ArrayBuffer {
  const cached = decoded.get(key);
  if (cached) return cached;
  const binary = atob(FONT_CHUNKS[key].join(""));
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  const buffer = bytes.buffer;
  decoded.set(key, buffer);
  return buffer;
}
